from pathlib import Path
import collections, re
files = [p for p in sorted(Path("repo").rglob("*.py")) if p.is_file()]
sen = collections.Counter()
detail = {}
for p in files:
    m = re.search(r"sentinel:\\s*(\\S+)", p.read_text())
    if m:
        sen[m.group(1)] += 1
        detail.setdefault(m.group(1), []).append(str(p))
print(sen)
for k,v in detail.items():
    print(k, len(v), v[:5])
print("--- any non-sentinel files:", [str(p) for p in files if not re.search(r"sentinel:", p.read_text())][:10])
`});
return out;

